<?php
namespace App\Services\DevOps;use App\Models\ZigoDevOpsRelease;
final class DeploymentDriftService {public function inspect(ZigoDevOpsRelease $release,bool $verifyFiles=false):array{$deployment=$release->deployment;$target=(string)config('zigo_devops.paths.'.$release->environment);$items=[];$overall='clean';foreach($deployment->files as $file){$path=$target.DIRECTORY_SEPARATOR.str_replace('/',DIRECTORY_SEPARATOR,$file->relative_path);$status='unknown';if(!$verifyFiles)$status='unknown';elseif(!is_file($path)){$status='missing';$overall='missing';}elseif($file->deployed_fingerprint&&hash_equals($file->deployed_fingerprint,hash_file('sha256',$path)))$status='clean';else{$status='modified';if($overall!=='missing')$overall='modified';}$items[]=['path'=>$file->relative_path,'status'=>$status];}if(!$verifyFiles)$overall='unknown';return['environment'=>$release->environment,'release_id'=>$release->id,'status'=>$overall,'verified_files'=>$verifyFiles,'files'=>$items,'checked_at'=>now()->toIso8601String()];}}
